  const hook = globalThis.__REACT_DEVTOOLS_GLOBAL_HOOK__;
  if (!hook) return 'no hook';
  let roots = [];
  hook.renderers.forEach((r, id) => {
    try { roots = roots.concat(Array.from(hook.getFiberRoots(id))); } catch (e) {}
  });
  const seen = new Set();
  const stack = roots.slice();
  const matches = [];
  while (stack.length) {
    const f = stack.pop();
    if (!f || seen.has(f)) continue;
    seen.add(f);
    const p = f.memoizedProps;
    if (p) {
      const c = p.children;
      const isTagText = c === '#caturday' || (Array.isArray(c) && c.includes('#caturday'));
      if (isTagText) matches.push({hasOnPress: typeof p.onPress, type: (f.type && (f.type.displayName || f.type.name)) || typeof f.type});
    }
    if (f.child) stack.push(f.child);
    if (f.sibling) stack.push(f.sibling);
  }
  return JSON.stringify({roots: roots.length, matches});
})()

